-- Forever-only route overrides for EXISTING transports whose real-world path
-- differs between clients (unlike forever_only, which is for a transport
-- that doesn't exist on Era at all -- see [11] above). [5]'s vessel ("The
-- Bravery") gained a third stop, Southshore (Hillsbrad Foothills), on
-- Forever only: Auberdine -> [continent jump] -> Menethil Harbor ->
-- Southshore -> [continent jump] -> Auberdine. Applied by NautCore.lua's
-- ApplyForeverRouteOverrides (InitialiseConfig, called before the normal
-- packedData decode loop, and ONLY when IS_FOREVER) by swapping these
-- tables' [id] entries into the corresponding main table (self.transports,
-- self.rtts, self.platforms, self.packedData) before decode runs -- the
-- decode loop itself needed no changes, since plat/trig/jump/zone tag
-- handling is already generic over however many indices exist.
--
-- Deliberately NOT structured as a new forever_only transport id (which
-- would have reused the [11]/PruneForeverOnlyTransports mechanism): that
-- mechanism only ever prunes an APPENDED id (the highest one), keeping
-- self.transports gap-free by construction. Pruning an EXISTING mid-range
-- id like [5] instead -- while a new appended id took over for Forever --
-- would leave a hole in the middle of the array on Forever specifically
-- (1,2,3,4,<gap>,6,7...), which #(transports)-based code elsewhere
-- (NextTransportInList, etc.) assumes never happens. Keeping [5] as [5] on
-- both clients, just with different content, avoids that entirely -- and
-- keeps self.db.global.knownCycles[5] meaningful across both clients too,
-- rather than orphaning it every time a player switches which client they
-- test on.
--
-- transitZones_forever is ADDITIVE (merged into self.transitZones, not
-- replacing it) since [5]'s existing Wetlands/Darkshore zone entries are
-- still correct on Forever -- only the new Southshore zone needs adding.
NauticusClassic.transportOverrides_forever = {
	[5] = {
		-- real travel order is Menethil -> Southshore -> Auberdine (see the
		-- packedData_forever[5] comment below), not Menethil -> Auberdine --
		-- Era's [5] keeps the original 2-zone name/short_name untouched either way
		name = L["Wetlands"]..ARROW..L["Hillsbrad Foothills"]..ARROW..L["Darkshore"],
		short_name = L["MH"]..ARROW..L["SS"]..ARROW..L["Aub"],
	},
}

