-- cycle relies entirely on ChatArrivalWatcher_OnMsg's active re-sync (a
-- direct SetKnownCycle call anchored at plat1), since the announcement is
-- a more precise arrival signal than inferring one from geometry.
-- triggers[12] being empty is safe -- the trigger loop just runs zero
-- iterations for this transport.
--
